using NetArchTest.Rules;

namespace PaymentAuthorization.ArchitectureTest.LayerBoundaries;

/// <summary>
/// Guards the Domain/Application/Infrastructure layering so a technical detail
/// (HTTP clients, file system, JSON serialization, ...) can never be reached for
/// from business code, and dependencies only point inward.
/// </summary>
public sealed class LayerBoundaryTests
{
    private const string DomainNamespace = "PaymentAuthorization.Domain";
    private const string ApplicationNamespace = "PaymentAuthorization.Application";
    private const string InfrastructureNamespace = "PaymentAuthorization.Infrastructure";

    private static readonly System.Reflection.Assembly DomainAssembly =
        typeof(Domain.Money).Assembly;

    private static readonly System.Reflection.Assembly ApplicationAssembly =
        typeof(Application.AuthorizePayment).Assembly;

    private static readonly System.Reflection.Assembly InfrastructureAssembly =
        typeof(Infrastructure.HttpPaymentGateway).Assembly;

    [Fact]
    public void Domain_does_not_depend_on_application_or_infrastructure()
    {
        var result = Types.InAssembly(DomainAssembly)
            .Should()
            .NotHaveDependencyOnAny(ApplicationNamespace, InfrastructureNamespace)
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Application_does_not_depend_on_infrastructure()
    {
        var result = Types.InAssembly(ApplicationAssembly)
            .Should()
            .NotHaveDependencyOn(InfrastructureNamespace)
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Domain_does_not_use_technical_framework_namespaces()
    {
        var result = Types.InAssembly(DomainAssembly)
            .Should()
            .NotHaveDependencyOnAny("System.Net.Http", "System.IO", "System.Text.Json")
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Application_does_not_use_technical_framework_namespaces()
    {
        var result = Types.InAssembly(ApplicationAssembly)
            .Should()
            .NotHaveDependencyOnAny("System.Net.Http", "System.IO", "System.Text.Json")
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    private static string Describe(NetArchTest.Rules.TestResult result) =>
        result.FailingTypes is null
            ? "Rule failed."
            : "Rule failed for: " + string.Join(", ", result.FailingTypes.Select(t => t.FullName));
}

